ALTER TABLE "flow_option_gaps" DROP CONSTRAINT "flow_option_gaps_check";--> statement-breakpoint
ALTER TABLE "flow_option_prints" DROP CONSTRAINT "flow_option_prints_check";--> statement-breakpoint
ALTER TABLE "flow_samples" DROP CONSTRAINT "flow_samples_check";--> statement-breakpoint
ALTER TABLE "flow_events" ADD CONSTRAINT "flow_events_check" CHECK (("flow_events"."symbol" in ('SPY', 'ES', 'QQQ', 'NQ') or ("flow_events"."symbol" in ('IWM', 'NVDA') and "flow_events"."source" = 'quantdata')) and "flow_events"."direction" in ('bullish', 'bearish', 'neutral') and "flow_events"."source" in ('ibkr', 'quantdata') and length("flow_events"."detail") <= 300 and length("flow_events"."key") <= 160);--> statement-breakpoint
ALTER TABLE "flow_option_gaps" ADD CONSTRAINT "flow_option_gaps_check" CHECK ("flow_option_gaps"."symbol" in ('SPY', 'ES', 'QQQ', 'NQ', 'IWM', 'NVDA') and "flow_option_gaps"."end_time" >= "flow_option_gaps"."start_time");--> statement-breakpoint
ALTER TABLE "flow_option_prints" ADD CONSTRAINT "flow_option_prints_check" CHECK ("flow_option_prints"."symbol" in ('SPY', 'ES', 'QQQ', 'NQ', 'IWM', 'NVDA') and "flow_option_prints"."ticker" in ('SPY', 'SPX', 'QQQ', 'NDX', 'IWM', 'NVDA') and "flow_option_prints"."right" in ('call', 'put') and "flow_option_prints"."premium" >= 0 and length("flow_option_prints"."id") <= 64);--> statement-breakpoint
ALTER TABLE "flow_samples" ADD CONSTRAINT "flow_samples_check" CHECK (("flow_samples"."symbol" in ('SPY', 'ES', 'QQQ', 'NQ') or ("flow_samples"."symbol" in ('IWM', 'NVDA') and "flow_samples"."source" = 'options')) and "flow_samples"."source" in ('ticks', 'depth', 'options', 'gex', 'net_drift', 'market_premium') and "flow_samples"."status" in ('ok', 'empty', 'unavailable', 'skipped') and "flow_samples"."items" >= 0 and length(coalesce("flow_samples"."message", '')) <= 300);